# Count significant figures
def sig_figs(x, n):
    if x == 0:
        return 0
    s = str(abs(x))
    if '.' in s:
        integer_part, decimal_part = s.split('.')
    else:
        integer_part = s
        decimal_part = ''
    # Count digits before decimal
    int_digits = len(integer_part)
    # We need n significant figures total
    if int_digits >= n:
        # Round to n significant figures
        return round(float(s), n - int_digits)
    else:
        # Need to add decimal places
        return round(float(s), n - int_digits)

