def sig_figs(x, n):
    if x == 0:
        return 0
    s = f"{abs(x):.10f}"
    # Count significant figures
    sig_count = 0
    for c in s.split('.')[0]:
        if c != '0':
            sig_count += 1
        else:
            break
    # Format to n significant figures
    if sig_count < n:
        return round(float(s), n - sig_count)
    else:
        return round(float(s), n - sig_count)

