import math
result = math.sin(math.sqrt(1.1))

# Round to 6 significant figures properly
def round_sig_figs(x, sig_figs):
    if x == 0:
        return 0
    if x >= 1:
        return round(x, sig_figs - 1)
    else:
        # For numbers between 0 and 1, we need to count decimal places
        # 0.866829... with 6 sig figs
        # We want 6 digits total starting from first non-zero
        # So we need to round to the 5th decimal place (since there's 1 digit before decimal)
        # Actually, let's think: 0.866829 has 6 sig figs if we keep 0.866830
        # The position of the 6th sig fig is at the 5th decimal place
        decimal_places = sig_figs - 1 - len(str(int(abs(x))))
        return round(x, decimal_places)

result_rounded = round_sig_figs(result, 6)
print(f"Result: {result}")
print(f"Rounded to 6 sig figs: {result_rounded}")

